	 public List<List<Integer>> threeSum(int[] nums) {
	       
		 int count=0;
	        int non=0;
	        List<List<Integer>> l=new ArrayList<>();
	        List t=Arrays.asList(nums);
	         int b=Collections.frequency(t, 0);
	        if(b>nums.length/2){
	        	      if(b==nums.length) {
	        	    	  LinkedList<Integer> a=new LinkedList<>();
	        	    	  a.add(0);
	        	    	  a.add(0);
	        	    	  a.add(0);
	        	    	  l.add(a);
	        	    	  return l;
	        	      }
	           
	               LinkedList<Integer> a=new LinkedList<>();
	               p:
	             for(int i=0;i<nums.length;i++){
	            	    if(non<3&&nums[i]==0){
	            	    	
	            	    if(a.size()==0)a.add(0);else {
	            	    	
	            	    	for(int j=a.size()-1;j>=0;j--) {
	            	    		if(a.get(j)==0||a.get(j)<0)	
	            	    			{a.add(j+1,0);
	            	    			break;}
	            	    			
	            	    		else if(a.get(j)>0) {if(j==0)a.add(0,nums[i]);continue;}
	            	    	}
	            	    }
	            	    	non++;}
	                if(nums[i]!=0){
	                if(i==0)
	                { a.add(nums[i]);}
	                else {
	                	count=0;
	                	int s=0;
	                	for(int j=a.size()-1;j>=0;j--) {
	                		s++;
	                		
	                		if(a.get(j)==nums[i]) {
	                			count++;
	                			if(count==2)continue p;
	                			
	                			}
	                		if(s==2)break;
	                  
	                	}
	                	a.add(nums[i]);
	                	Collections.sort(a);
	                }
	              
	             }}
	       

	        q:
	        for(int i=0;i<a.size()-2;i++){
	            if(a.get(i)>0)break;
	            if(i!=0&&a.get(i)==a.get(i-1))continue;
	                
	            l:
	            for(int j=i+1;j<a.size()-1;j++){
	                if(-a.get(i)<a.get(j))continue q;
	                if(j!=i+1&&a.get(j)==a.get(j-1))continue;
	                
	                for(int k=j+1;k<a.size();k++){
	                     if(a.get(i)+a.get(j)+a.get(k)==0){
	                        ArrayList<Integer> all=new ArrayList<>();
	                        all.add(a.get(i));
	                        all.add(a.get(j));
	                        all.add(a.get(k));
	                        
	                        
	                            l.add(all);
	                        
	                       
	                       continue l;
	                     }
	                }
	            }
	        }
	             
	              
	              
	        
	        return l;
	          }else {   
	        count=0;
	        Arrays.sort(nums);                 
	        q:
	        for(int i=0;i<nums.length-2;i++){
	            if(nums[i]>0)break;
	            if(i!=0&&nums[i]==nums[i-1])continue;
	                
	            l:
	            for(int j=i+1;j<nums.length-1;j++){
	                if(-nums[i]<nums[j])continue q;
	                if(j!=i+1&&nums[j]==nums[j-1])continue;
	                
	                for(int k=j+1;k<nums.length;k++){
	                     if(nums[i]+nums[j]+nums[k]==0){
	                        ArrayList<Integer> al=new ArrayList<>();
	                        al.add(nums[i]);
	                        al.add(nums[j]);
	                        al.add(nums[k]);
	                        int n=1;
	                        if(count==0){
	                            l.add(al);
	                        }else{
	                            l.add(al);
	                        }
	                       count++;
	                       continue l;
	                     }
	                }
	            }
	        }}
	        
	    return l;    
	    }
